export const SHOCKWAVE=Object.freeze({radius:8,speed:17,gravity:20,fuse:.22,maxAge:3,maxHorizontal:18,maxVertical:16});
export function shockwaveImpulse(center,position){const dx=position[0]-center[0],dy=Math.max(0,position[1]-center[1]),dz=position[2]-center[2],distance=Math.hypot(dx,dy,dz);if(distance>=SHOCKWAVE.radius)return [0,0,0];const strength=1-distance/SHOCKWAVE.radius,horizontal=Math.hypot(dx,dz),denom=Math.max(1.5,horizontal,dy);return [dx/denom*SHOCKWAVE.maxHorizontal*strength,(7+SHOCKWAVE.maxVertical*strength)*Math.min(1,1.5-distance*.04),dz/denom*SHOCKWAVE.maxHorizontal*strength];}
export function fallDamage(velocity){return Math.min(100,Math.max(0,Math.round((Math.abs(Math.min(0,velocity))-12)*4)));}
export function resolveLanding(p,velocity){const damage=p.shockwaveImmune?0:fallDamage(velocity);p.hp=Math.max(0,p.hp-damage);p.shockwaveImmune=false;return damage;}
export function throwGrenade(p,input,id){const cp=Math.cos(input.pitch),direction=[-Math.sin(input.yaw)*cp,Math.sin(input.pitch),-Math.cos(input.yaw)*cp];return {id,owner:p.id,position:[p.p[0],p.p[1]+1.4,p.p[2]],velocity:direction.map(v=>v*SHOCKWAVE.speed),age:0,landed:false,trigger:SHOCKWAVE.fuse};}
